// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{})
}

// ServeMux is an abstraction of [http.ServeMux].
type ServeMux interface {
	HandleFunc(pattern string, handler func(http.ResponseWriter, *http.Request))
	http.Handler
}

type StdHTTPServerOptions struct {
	BaseURL          string
	BaseRouter       ServeMux
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, m ServeMux) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseRouter: m,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, m ServeMux, baseURL string) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseURL:    baseURL,
		BaseRouter: m,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options StdHTTPServerOptions) http.Handler {
	m := options.BaseRouter

	if m == nil {
		m = http.NewServeMux()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}

	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/models", wrapper.ListAdminModels)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/models", wrapper.CreateModel)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/models/{model_id}", wrapper.GetModel)
	m.HandleFunc(http.MethodPatch+" "+options.BaseURL+"/models/{model_id}", wrapper.UpdateModel)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/models/{model_id}/prices", wrapper.GetModelPrices)
	m.HandleFunc(http.MethodPut+" "+options.BaseURL+"/models/{model_id}/prices", wrapper.PutModelPrices)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/providers", wrapper.ListProviders)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/providers", wrapper.CreateProvider)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/providers/{provider_id}", wrapper.GetProvider)
	m.HandleFunc(http.MethodPatch+" "+options.BaseURL+"/providers/{provider_id}", wrapper.UpdateProvider)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/providers/{provider_id}/api-keys", wrapper.ListProviderAPIKeys)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/providers/{provider_id}/api-keys", wrapper.CreateProviderAPIKey)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/provider-api-keys/{bifrost_key_id}", wrapper.GetProviderAPIKey)
	m.HandleFunc(http.MethodPatch+" "+options.BaseURL+"/provider-api-keys/{bifrost_key_id}", wrapper.UpdateProviderAPIKey)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/provider-api-keys/{bifrost_key_id}/disable", wrapper.DisableProviderAPIKey)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/provider-api-keys/{bifrost_key_id}/billing", wrapper.GetProviderAPIKeyBilling)
	m.HandleFunc(http.MethodPut+" "+options.BaseURL+"/provider-api-keys/{bifrost_key_id}/billing", wrapper.PutProviderAPIKeyBilling)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/provider-api-keys/{bifrost_key_id}/prices", wrapper.GetProviderAPIKeyPrices)
	m.HandleFunc(http.MethodPut+" "+options.BaseURL+"/provider-api-keys/{bifrost_key_id}/prices", wrapper.PutProviderAPIKeyPrices)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/ai-orders", wrapper.ListAIOrders)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/charge-outbox", wrapper.ListChargeOutbox)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/bifrost-logs", wrapper.ListBifrostLogs)

	return m
}

